/* ---------- action log, standard list ---------- */
.al{max-width:420px}
.al-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}
.al-head .t{font-size:15px;font-weight:600}
.al-list{padding:8px 16px 12px}
.al-row{position:relative;display:flex;align-items:flex-start;gap:12px;padding:8px 0;animation:enter .35s var(--ease) both}
.al-row:not(:last-child)::before{content:"";position:absolute;left:14px;top:40px;bottom:-4px;width:1px;background:var(--line)}
.al-ic{width:28px;height:28px;flex:none;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--icon-bg);color:var(--text-dim)}
.al-tx{flex:1;min-width:0}
.al-tx .t{font-size:13.5px;font-weight:500;color:var(--text)}
.al-tx .d{margin-top:2px;font-size:12.5px;color:var(--muted)}
.al-tx code{font-family:var(--mono);font-size:12.5px}
.al-time{margin-top:6px;white-space:nowrap}
.al-st{width:18px;height:18px;flex:none;margin-top:5px;display:grid;place-items:center}
[data-style="soft"] .al{border-radius:20px}
[data-style="soft"] .al-ic{border:0;border-radius:9px;background:var(--chip)}
[data-style="soft"] .al-tx code{font-family:var(--sans);font-weight:600}

/* ---------- 07 action log ---------- */
{
  const list = $('#al-list'), pill = $('#al-pill');
  const steps = [
    ['description','Read <code>Pricing.tsx</code>','src/pages, 212 lines','0.4s'],
    ['search','Searched Figma for <code>Button</code>','6 matches in Components.fig','1.1s'],
    ['edit_note','Edited <code>Button.tsx</code>','<span class="plus">+18</span> <span class="minus">-7</span> lines','2.3s'],
    ['terminal','Ran <code>npm test</code>','24 tests passed','3.2s'],
    ['link','Opened a pull request','#412, Use shared button tokens','0.6s']
  ];
  let ts = [];
  function run(){
    ts.forEach(clearTimeout); ts = []; list.innerHTML = ''; setPill(pill, 'prog', 'Running');
    steps.forEach((st, i) => ts.push(setTimeout(() => {
      const prev = list.lastElementChild; if (prev){ prev.querySelector('.al-st').innerHTML = ic('check_circle', 'sm s-done icon-in'); prev.querySelector('.al-time').textContent = steps[i - 1][3]; }
      const row = document.createElement('div'); row.className = 'al-row';
      row.innerHTML = `<span class="al-ic">${ic(st[0],'sm')}</span><div class="al-tx"><div class="t">${st[1]}</div><div class="d">${st[2]}</div></div><span class="mono-xs al-time"></span><span class="al-st"><i class="spin"></i></span>`;
      morph(list.parentElement, () => list.appendChild(row)); ambient('c7', 'tick');
    }, 200 + i * 900)));
    ts.push(setTimeout(() => {
      const prev = list.lastElementChild; prev.querySelector('.al-st').innerHTML = ic('check_circle', 'sm s-done icon-in'); prev.querySelector('.al-time').textContent = steps[steps.length - 1][3];
      setPill(pill, 'done', '5 steps, 7.6s'); ambient('c7', 'done');
    }, 200 + steps.length * 900));
  }
  $('#al-replay').addEventListener('click', () => { Sound.play('tab'); run(); });
  whenSeen($('#c7'), run);
}
